import React, { useEffect, useState } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";
import Swal from "sweetalert2";

export default function ParentFeePage() {
  const [admissionNo, setAdmissionNo] = useState("");
  const [summary, setSummary] = useState(null);
  const [amount, setAmount] = useState("");
  const [structure, setStructure] = useState(null); // overall structure

  // Load overall school fee structure
  useEffect(() => {
    axios
      .get("http://localhost:5000/api/fees")
      .then((res) => {
        if (res.data.success) setStructure(res.data.data);
      })
      .catch(() => toast.error("Failed to load overall fee structure"));
  }, []);

  // Fetch student-specific fee summary
  const fetchFee = async () => {
    if (!admissionNo.trim()) return toast.error("Please enter admission number");
    try {
      const res = await axios.get(
        `http://localhost:5000/api/fees/student/${admissionNo}`
      );
      if (res.data.success && res.data.data) {
        setSummary(res.data.data);
        toast.success("Fee record loaded!");
      } else {
        setSummary(null);
        toast.error("No record found!");
      }
    } catch (err) {
      console.error(err);
      toast.error("Failed to load fee structure");
    }
  };

  // Simulated payment
  const payNow = async () => {
    const amt = Number(amount);
    if (!amt || amt <= 0) return toast.error("Enter valid amount");

    const ok = await Swal.fire({
      title: `Pay ₹${amt}?`,
      text: "Proceed to simulated payment?",
      showCancelButton: true,
    });
    if (!ok.isConfirmed) return;

    try {
      const res = await axios.post("http://localhost:5000/api/fees/pay", {
        admissionNo,
        amount: amt,
        method: "simulated",
      });

      if (res.data.success) {
        const updated = await axios.get(
          `http://localhost:5000/api/fees/student/${admissionNo}`
        );
        const feeData = updated.data?.data?.fee;
        const remaining = feeData?.remaining || 0;

        await Swal.fire({
          icon: "success",
          title: "Payment Successful!",
          html: `
            <p><b>Amount Paid:</b> ₹${amt}</p>
            <p><b>Remaining Fee:</b> ₹${remaining}</p>
          `,
          confirmButtonText: "OK",
        });

        setSummary(null);
        setAdmissionNo("");
        setAmount("");
      } else {
        toast.error(res.data.error || "Payment failed");
      }
    } catch (err) {
      console.error(err);
      toast.error("Payment failed");
    }
  };

  const getTotal = (items) => {
    if (!items) return 0;
    return Object.values(items).reduce((sum, item) => sum + (item.amount || 0), 0);
  };

  return (
    <div className="fee-page">
      <Toaster />

      {/* Overall school fee */}
      {structure && structure.items && (
        <div className="overall-structure">
          <h2>School Fee Structure ({structure.academicYear})</h2>
          <div dangerouslySetInnerHTML={{ __html: structure.notes }} />
          <table className="fee-table">
            <thead>
              <tr>
                <th>Particulars</th>
                <th>Amount (₹)</th>
              </tr>
            </thead>
            <tbody>
              {structure.items.map((item) => (
                <tr key={item.key}>
                  <td>{item.title}</td>
                  <td>₹{item.amount.toLocaleString()}</td>
                </tr>
              ))}
              <tr className="fee-total">
                <td><b>Total</b></td>
                <td><b>₹{getTotal(structure.items.reduce((obj, i) => ({ ...obj, [i.key]: i }), {}))}</b></td>
              </tr>
            </tbody>
          </table>
        </div>
      )}

      {/* Admission number input */}
      <div className="search-box" style={{ marginTop: "30px" }}>
        <h3>💳 Pay School Fees</h3>
        <input
          type="text"
          value={admissionNo}
          onChange={(e) => setAdmissionNo(e.target.value)}
          placeholder="Enter Admission Number (e.g. KV-668272)"
        />
        <button onClick={fetchFee}>Search</button>
      </div>

      {!summary && (
        <p className="info-text">Enter admission number to view personal fee details.</p>
      )}

      {/* Student-specific section */}
      {summary && summary.fee && (
        <div className="fee-card">
          <h3>
            Fee Structure for {summary.student.studentName} ({summary.student.admissionNo})
          </h3>
          <table className="fee-table">
            <thead>
              <tr>
                <th>Particulars</th>
                <th>Amount (₹)</th>
              </tr>
            </thead>
            <tbody>
              {Object.keys(summary.fee.items || {}).map((key) => (
                <tr key={key}>
                  <td>{summary.fee.items[key].title}</td>
                  <td>₹{summary.fee.items[key].amount.toLocaleString()}</td>
                </tr>
              ))}
              <tr className="fee-total">
                <td><b>Total</b></td>
                <td><b>₹{summary.fee.total.toLocaleString()}</b></td>
              </tr>
              <tr>
                <td>Paid</td>
                <td>₹{summary.fee.paid.toLocaleString()}</td>
              </tr>
              <tr>
                <td>Remaining</td>
                <td>₹{summary.fee.remaining.toLocaleString()}</td>
              </tr>
            </tbody>
          </table>

          <div className="pay-section">
            <input
              type="number"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              placeholder="Enter amount to pay"
            />
            <button onClick={payNow}>Pay Now</button>
            <button
              onClick={() => setAmount(summary.fee.remaining)}
              style={{ marginLeft: "10px" }}
            >
              Pay Full
            </button>
          </div>
        </div>
      )}
    </div>
  );
}































